const rss_feeds = [
  "https://hnrss.org/frontpage",
  "https://feeds.bbci.co.uk/news/technology/rss.xml"
];

const topics = [
  "agentic workflows",
  "model context protocol",
  "vector databases",
  "prompt injection",
  "postgres embeddings"
];

const config = {
  cache_ttl_minutes: 90,
  dedupe_ttl_days: 21,
  min_score: 6,
  max_items_total: 45,
  max_per_source: 16,
  max_per_topic: 8,
  enable_llm_summary: true,
  timeout_ms: 12000,
  GITHUB_TOKEN: $env.GITHUB_TOKEN || "",
  ZAI_API_KEY: $env.ZAI_API_KEY || "",
  ZAI_BASE_URL: $env.ZAI_BASE_URL || "https://api.z.ai/api/paas/v4",
  ZAI_MODEL: $env.ZAI_MODEL || "glm-5"
};

const st = $getWorkflowStaticData('global');
st.runs = (st.runs || 0) + 1;

return [{ json: { rss_feeds, topics, config, run_id: st.runs } }];

const items = $input.all();
const output = items.flatMap(item => {
  const feed = item.json;
  const entries = feed.items || [];
  return entries.map(entry => {
    return {
      json: {
        source: "rss",
        topic: null,
        title: entry.title || "Untitled",
        url: entry.link || entry.guid || "",
        published_at: entry.pubDate || entry.isoDate || null,
        raw_score: 5,
        score: 5,
        summary_raw: entry.contentSnippet || entry.description || null,
        summary: null,
        meta: { author: feed.title || null, venue: "RSS Feed", cached: false }
      }
    };
  });
});
return output;

const topic = $json.topic;
const config = $('Init').first().json.config;
const st = $getWorkflowStaticData('global');

if (!st.cache) st.cache = {};

const now = Date.now();
const ttl_ms = config.cache_ttl_minutes * 60 * 1000;

// Prune old entries
for (const k in st.cache) {
  if (now - st.cache[k].ts_epoch_ms > ttl_ms) delete st.cache[k];
}

const cached = st.cache[topic];
if (cached && (now - cached.ts_epoch_ms < ttl_ms)) {
  return [{ json: { topic, config, cache_hit: true, cached_items: cached.items || [] } }];
}

return [{ json: { topic, config, cache_hit: false, cached_items: [] } }];

