const topic = $('Cache Gate').first().json.topic;
const items = $input.all().map(i => i.json);
const st = $getWorkflowStaticData('global');
st.cache = st.cache || {};
st.cache[topic] = { ts_epoch_ms: Date.now(), items: items };
return items.map(i => ({ json: i }));

const init = $('Init').first().json;
const config = init.config;
const topics = init.topics;
const st = $getWorkflowStaticData('global');
st.seen = st.seen || {};

const now = Date.now();
const dedupe_ttl_ms = config.dedupe_ttl_days * 24 * 60 * 60 * 1000;

// Prune seen
Object.keys(st.seen).forEach(k => {
  if (now - st.seen[k] > dedupe_ttl_ms) delete st.seen[k];
});

const items = $input.all().map(x => x.json).filter(i => !i.__skip);
const candidates_total = items.length;

// Canonicalize URL
const canon = (u) => {
  if (!u) return null;
  try {
    let url = new URL(u);
    url.hostname = url.hostname.toLowerCase();
    [...url.searchParams.keys()].filter(k => k.startsWith('utm_')).forEach(k => url.searchParams.delete(k));
    let s = url.toString();
    if (s.endsWith('/')) s = s.slice(0, -1);
    return s;
  } catch { return null; }
};

const processed = items.filter(i => {
  const c = canon(i.url);
  if (!c) return false;
  i.url = c;
  if (st.seen[c]) return false;
  st.seen[c] = now;
  return true;
});

// Score
processed.forEach(i => {
  const pub = i.published_at ? new Date(i.published_at).getTime() : 0;
  const age_hours = pub ? (now - pub) / 3600000 : 96;
  let s = Math.max(0, i.raw_score - 0.12 * age_hours);
  if (i.source === 'hn') s += 3;
  if (i.source === 'github') s += 2;
  if (i.source === 'crossref') s += 1;
  if (i.source === 'openalex') s += 1;
  i.score = s;
});

const filtered = processed.filter(i => i.score >= config.min_score).sort((a,b) => b.score - a.score);

// Diversity Caps
const sourceCounts = {};
const topicCounts = {};
const final = [];
for (const i of filtered) {
  const sc = (sourceCounts[i.source] || 0);
  const tc = (topicCounts[i.topic] || 0);
  if (sc >= config.max_per_source || tc >= config.max_per_topic) continue;
  final.push(i);
  sourceCounts[i.source] = sc + 1;
  topicCounts[i.topic] = tc + 1;
  if (final.length >= config.max_items_total) break;
}

const stats = {
  candidates_total,
  final_items: final.length,
  cached_items_count: final.filter(i => i.meta.cached).length,
  cache_miss_topics_count: (() => {
    let count = 0;
    try {
      const gateItems = $('Cache Gate').all();
      for (const item of gateItems) {
        if (item.json.cache_hit === false) count++;
      }
    } catch(e) {}
    return count;
  })(),
  api_calls_estimate: 4 * cache_miss_topics_count,
  by_source: {}
};
final.forEach(i => stats.by_source[i.source] = (stats.by_source[i.source] || 0) + 1);

return [{ json: {
  config,
  topics,
  stats,
  items: final,
  run_id: $('Init').first().json.st_runs || 0,
  generated_at: new Date().toISOString()
}}];

const data = $input.first().json;
const top = data.items.slice(0, 12);
const list = top.map(i => `- URL: ${i.url}\n  Title: ${i.title}\n  Source: ${i.source}\n  Topic: ${i.topic || 'N/A'}\n  Score: ${i.score.toFixed(1)}`).join('\n');
return [{ json: {
  __baseData: data,
  llm_body: {
    messages: [{
      role: "user",
      content: `Analyze these items and return ONLY JSON:\n${list}\n\nRequired JSON format:\n{"summaries":[{"url":"...","summary":"1 sentence","tags":["t1","t2"]}]}`
    }]
  }
}}];

const base = $('Prepare LLM').first().json.__baseData;
const resp = $input.first().json;
let summaries = [];
try {
  const content = resp.choices?.[0]?.message?.content;
  if (content) summaries = JSON.parse(content).summaries || [];
  else if (resp.summaries) summaries = resp.summaries;
} catch (e) {}

const map = {};
summaries.forEach(s => map[s.url] = s);
const items = base.items.map(i => {
  const s = map[i.url] || {};
  return { ...i, summary: s.summary || i.summary_raw || i.title, tags: s.tags || [] };
});
return [{ json: { ...base, items } }];

const data = $input.first().json;
const items = data.items.map(i => ({
  ...i,
  summary: i.summary_raw || i.title,
  tags: []
}));
return [{ json: { ...data, items } }];

const data = $input.first().json;
if (!data.items || !Array.isArray(data.items)) throw new Error('Invalid items');
for (const i of data.items) {
  if (typeof i.url !== 'string' || !i.url) throw new Error('Missing URL');
  if (typeof i.score !== 'number') throw new Error('Invalid score');
}
const str = JSON.stringify(data);
if (str.includes('{{')) throw new Error('Template detected');
return [{ json: data }];

const data = $input.first().json;
const groups = {};
data.items.forEach(i => {
  const s = i.source || 'unknown';
  const t = i.topic || 'general';
  groups[s] = groups[s] || {};
  groups[s][t] = groups[s][t] || [];
  groups[s][t].push(i);
});

let md = `# AegisPulse Briefing\n\n`;
Object.keys(groups).sort().forEach(s => {
  md += `## ${s.toUpperCase()}\n`;
  Object.keys(groups[s]).sort().forEach(t => {
    md += `### ${t}\n`;
    groups[s][t].forEach(i => {
      md += `- [${i.score.toFixed(1)}] [${i.title}](${i.url})\n  ${i.summary}\n\n`;
    });
  });
});

return [{ json: {
  run_id: data.run_id,
  generated_at: data.generated_at,
  topics: data.topics,
  stats: data.stats,
  items: data.items,
  digest_markdown: md
}}];
